<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\UserProfileWebsiteUrlVO;

trait UserProfileWebsiteUrlAttributeHolder
{
    protected UserProfileWebsiteUrlVO|string|null $websiteUrl = null;
    protected bool $websiteUrlAssigned = false;

    public function getWebsiteUrlOrCurrent(?UserProfileWebsiteUrlVO $websiteUrl): ?UserProfileWebsiteUrlVO
    {
        return $this->websiteUrlAssigned ? ($this->websiteUrl === null ? null : UserProfileWebsiteUrlVO::from($this->websiteUrl)) : $websiteUrl;
    }
    public function websiteUrlTryBuildInitial(ConstraintFailList $error): ?UserProfileWebsiteUrlVO
    {
        return  UserProfileWebsiteUrlVO::tryFrom($this->websiteUrlAssigned ? $this->websiteUrl : null, $error);
    }
    public function websiteUrl(UserProfileWebsiteUrlVO|string|null $websiteUrl): static
    {
        $this->websiteUrl = $websiteUrl;
        $this->websiteUrlAssigned = true;
        return $this;
    }
    public function getWebsiteUrl(): ?string
    {
        return $this->websiteUrl instanceof UserProfileWebsiteUrlVO ? $this->websiteUrl->value() : $this->websiteUrl;
    }
    public function isWebsiteUrlAssigned(): bool
    {
        return $this->websiteUrlAssigned;
    }
    public function writeWebsiteUrlTo(mixed $att): void
    {
        if ($this->websiteUrlAssigned) {
            $att->websiteUrl($this->websiteUrl);
        }
    }
    public function readWebsiteUrlFrom(mixed $att): void
    {
        if ($att->isWebsiteUrlAssigned()) {
            $websiteUrl = $att->getWebsiteUrl();
            $this->websiteUrl($websiteUrl);
        }
    }
    public function unsetWebsiteUrl(): static
    {
        $this->websiteUrlAssigned = false;
        return $this;
    }
    protected function withDefaultWebsiteUrl(): void
    {
    }
    protected function withAssertedWebsiteUrlRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->websiteUrlAssigned = $this->websiteUrlAssigned) {
            $value->websiteUrl = UserProfileWebsiteUrlVO::tryFrom($this->websiteUrl, $errorsList);
        }
    }
}
